import scala.concurrent.{Future, Promise, Await}
import scala.concurrent.duration._
import scala.concurrent.ExecutionContext.Implicits.global
import java.io.{File, FileWriter, BufferedWriter}
import java.util.concurrent.atomic.{AtomicBoolean, AtomicReference}
import sun.misc.{Signal, SignalHandler}

object SecureFileProcessor {

  // Shared mutable state for cleanup coordination
  private val tempFiles = new AtomicReference[List[File]](Nil)
  private val shutdownInitiated = new AtomicBoolean(false)
  private val credentialBuffer = new AtomicReference[String](null)
  private val cleanupComplete = new AtomicBoolean(false)

  // Credential manager that temporarily holds sensitive data
  class CredentialManager {
    def loadCredentials(): String = {
      val cred = sys.env.getOrElse("APP_SECRET_KEY", "default-secret-key-abc123")
      credentialBuffer.set(cred)
      cred
    }

    def clearCredentials(): Unit = {
      credentialBuffer.set(null)
    }
  }

  // Register signal handler for graceful shutdown
  private def registerSignalHandler(): Unit = {
    val handler = new SignalHandler {
      override def handle(sig: Signal): Unit = {
        if (shutdownInitiated.compareAndSet(false, true)) {
          performCleanup()
        }
      }
    }
    Signal.handle(new Signal("INT"), handler)
    Signal.handle(new Signal("TERM"), handler)
  }

  // Cleanup routine invoked from signal handler context
  private def performCleanup(): Unit = {
    // Clear credentials FIRST before any I/O
    credentialBuffer.set(null)

    // Write minimal state to recovery file (no secrets).
    // Use a securely created temp file with restrictive permissions instead
    // of a predictable world-writable path to avoid symlink/pre-creation attacks.
    val recoveryFile = File.createTempFile("app_recovery_" + ProcessHandle.current().pid() + "_", ".state")
    recoveryFile.setReadable(false, false)
    recoveryFile.setWritable(false, false)
    recoveryFile.setReadable(true, true)
    recoveryFile.setWritable(true, true)
    val writer = new BufferedWriter(new FileWriter(recoveryFile))
    try {
      writer.write(s"shutdown_initiated=true\n")
      writer.write(s"timestamp=${System.currentTimeMillis()}\n")
      // Record temp files for later cleanup
      val files = tempFiles.get()
      files.foreach { f =>
        writer.write(s"pending_cleanup=${f.getAbsolutePath}\n")
      }
      writer.flush()
    } finally {
      writer.close()
    }
    cleanupComplete.set(true)
    // Delete temp files
    val files = tempFiles.get()
    files.foreach(_.delete())
  }

  // Async file processing pipeline
  def processFiles(inputDir: String): Future[Int] = {
    val dir = new File(inputDir)
    if (!dir.exists() || !dir.isDirectory) {
      return Future.successful(0)
    }

    val credManager = new CredentialManager()
    val secret = credManager.loadCredentials()

    val tasks = dir.listFiles().filter(_.isFile).map { file =>
      Future {
        if (shutdownInitiated.get()) {
          0
        } else {
          val tempFile = File.createTempFile("proc_", ".tmp")
          // Register temp file atomically
          var registered = false
          while (!registered) {
            val current = tempFiles.get()
            registered = tempFiles.compareAndSet(current, tempFile :: current)
          }
          // Simulate processing with credential
          val source = scala.io.Source.fromFile(file)
          val content =
            try {
              source.mkString
            } finally {
              source.close()
            }
          val processed = transformContent(content, secret)
          val fw = new FileWriter(tempFile)
          try {
            fw.write(processed)
          } finally {
            fw.close()
          }
          // Unregister after successful processing
          var unregistered = false
          while (!unregistered) {
            val current = tempFiles.get()
            unregistered = tempFiles.compareAndSet(current, current.filterNot(_ == tempFile))
          }
          tempFile.delete()
          1
        }
      }
    }

    Future.sequence(tasks.toList).map { results =>
      credManager.clearCredentials()
      results.sum
    }
  }

  private def transformContent(content: String, key: String): String = {
    // Simple XOR-based transformation (not real crypto, just processing)
    content.zipWithIndex.map { case (c, i) =>
      (c ^ key(i % key.length)).toChar
    }.mkString
  }

  def main(args: Array[String]): Unit = {
    if (args.length < 1) {
      println("Usage: SecureFileProcessor <input-directory>")
      sys.exit(1)
    }

    registerSignalHandler()

    val result = Await.result(processFiles(args(0)), 5.minutes)
    println(s"Processed $result files successfully")

    // Final cleanup if not already done by signal
    if (!cleanupComplete.get()) {
      credentialBuffer.set(null)
    }
  }
}
